names=sys.argv[1:] or list(A)
def run(n):
    ref,style,brief=A[n]; out=f'{S}/raw/{n}.png'
    if os.path.exists(out): return n,'exists'
    cmd=[G,'--out',out]
    for r in ref: cmd+=['--ref',f'{S}/ref/{r}.png']
    cmd+=[style+' '+brief]
    p=subprocess.run(cmd,capture_output=True,text=True,timeout=900)
    return n,(p.stdout.strip().splitlines()[-1] if p.returncode==0 and p.stdout.strip() else 'FAILED '+p.stdout[-300:]+p.stderr[-300:])
with cf.ThreadPoolExecutor(4) as e:
    for n,r in e.map(run,names): print(n,r[:150],flush=True)
